sys_script_include.script:
var BudgetSpreadsheetTotal = Class.create();
BudgetSpreadsheetTotal.prototype = {

    // Runs automatically when you call "new BudgetSpreadsheetTotal()". Holds all config in one place.
    initialize: function() {
        // The table that stores budget application records - REPLACE with your real table name
        this.TABLE_NAME = 'x_1962601_budget_t_budget';
        // The column name of the total amount field - REPLACE with your real column name
        this.TOTAL_FIELD = 'total_allocated';
        // The exact header text in the spreadsheet whose column holds the line item values
        this.AMOUNT_HEADER = 'Amount';
        // ZERO-BASED sheet index: 0 is the first sheet, 1 is the second, etc.
        this.SHEET_INDEX = 0;
        // ZERO-BASED header row index: 0 means headers are in spreadsheet row 1
        this.HEADER_ROW_INDEX = 0;
    },

    /**
     * Main entry point. Reads every spreadsheet attached to one budget record,
     * adds up all the line items, and writes the net figure back to the record.
     * @param recordSysId - sys_id of the budget application record
     * @return Object {total, rows, files} or null if called without a record
     */
    recalculate: function(recordSysId) {
        // Stop immediately if we were called without a record to work on
        if (!recordSysId)
            return null;

        // Running total that every valid line item gets added to
        var netTotal = 0;
        // Counts the line items read, so we can report it back to the user later
        var rowCount = 0;
        // Counts how many spreadsheet files were parsed SUCCESSFULLY
        var fileCount = 0;

        // Open a query against the attachment table to find this record's files
        var att = new GlideRecord('sys_attachment');
        // Restrict to attachments that belong to the budget application table
        att.addQuery('table_name', this.TABLE_NAME);
        // Restrict further to attachments on this one specific record
        att.addQuery('table_sys_id', recordSysId);
        // Read them oldest first so log output is in a predictable order
        att.orderBy('sys_created_on');
        // Send the query to the database
        att.query();

        // Loop through every attachment found on the record
        while (att.next()) {
            // Pull the file name out as a plain string so we can inspect the extension
            var fileName = att.getValue('file_name') + '';
            // Skip anything that is not an .xlsx file (PDFs, images, signed approvals, etc.)
            if (!this._isSpreadsheet(fileName))
                continue;
            // Parse this one file; returns {total, rows, parsed}
            var result = this._parseAttachment(att.getUniqueValue(), fileName);
            // Only count this file if it actually parsed and had the expected column
            if (result.parsed)
                fileCount++;
            // Add this file's subtotal into the overall running total
            netTotal += result.total;
            // Add this file's line item count into the overall count
            rowCount += result.rows;
        }

        // If no spreadsheet parsed successfully, leave the existing total untouched
        if (fileCount === 0) {
            // Write an informational entry to the system log for troubleshooting
            gs.info('BudgetSpreadsheetTotal: no readable .xlsx attachment found on ' + recordSysId);
            // Return a result object so the caller knows nothing was changed
            return {
                total: null,
                rows: 0,
                files: 0
            };
        }

        // Save the calculated figure onto the budget application record
        this._writeTotal(recordSysId, netTotal);

        // Hand the numbers back so a UI Action can show them in a message
        return {
            total: netTotal,
            rows: rowCount,
            files: fileCount
        };
    },

    /**
     * Decides whether a given file name is one we should try to parse.
     * Kept separate so the rule is defined in exactly one place.
     */
    _isSpreadsheet: function(fileName) {
        // Lower-case the name so ".XLSX" and ".xlsx" are treated the same
        var lower = ('' + fileName).toLowerCase();
        // Return true only when the last five characters are ".xlsx"
        return lower.slice(-5) === '.xlsx';
    },

    /**
     * Opens one attachment, walks its rows, and totals the amount column.
     * @return Object {total: Number, rows: Number, parsed: Boolean}
     */
    _parseAttachment: function(attachmentSysId, fileName) {
        // Subtotal for just this one file
        var total = 0;
        // Number of usable line items found in just this one file
        var rows = 0;

        // Create the platform's Excel parser (lives in the sn_impex scope)
        var parser = new sn_impex.GlideExcelParser();
        // Point the parser at the first worksheet - this index is ZERO-BASED
        parser.setSheetNumber(this.SHEET_INDEX);
        // Tell the parser the headers sit in spreadsheet row 1 - also ZERO-BASED
        parser.setHeaderRowNumber(this.HEADER_ROW_INDEX);
        // Ask the parser to return empty strings instead of null for blank cells
        parser.setNullToEmpty(true);

        // Create the attachment API object used to read file content
        var attachmentApi = new GlideSysAttachment();
        // Get a readable stream of the attachment's binary content
        var stream = attachmentApi.getContentStream(attachmentSysId);

        // Feed the stream into the parser; returns false if the file could not be read
        if (!parser.parse(stream)) {
            // Log the parser's own error text so support can see why it failed
            gs.error('BudgetSpreadsheetTotal: could not parse "' + fileName + '" - ' + parser.getErrorMessage());
            // Flag the failure so recalculate() does not count this as a processed file
            return {
                total: 0,
                rows: 0,
                parsed: false
            };
        }

        // Read the header names the parser actually found, as an array of strings
        var headers = parser.getColumnHeaders();

        // Log them every run - this single line makes most parsing problems obvious
        gs.info('BudgetSpreadsheetTotal: "' + fileName + '" headers found: [' + headers + ']');

        // If our expected column is missing, stop now rather than silently totalling zero
        if (headers.indexOf(this.AMOUNT_HEADER) === -1) {
            // Tell the reader exactly what was expected and what was actually present
            gs.error('BudgetSpreadsheetTotal: column "' + this.AMOUNT_HEADER +
                '" not found in ' + fileName + '. Headers present: [' + headers + ']');
            // Flag the failure so recalculate() does not count this as a processed file
            return {
                total: 0,
                rows: 0,
                parsed: false
            };
        }

        // Move to the next data row; returns false once every row has been read
        while (parser.next()) {
            // Get the current row as an object keyed by column header, e.g. {"Line Item":"CLIN001", Amount:"-4050"}
            var row = parser.getRow();
            // Pull out the value sitting under the "Amount" header
            var rawValue = row[this.AMOUNT_HEADER];

            // Skip blank cells - these are usually spacer or footer rows
            if (rawValue === null || rawValue === undefined || ('' + rawValue).trim() === '')
                continue;

            // Convert the text cell into a real number, handling $, commas and brackets
            var amount = this._toNumber(rawValue);

            // If the cell was not numeric at all, warn and move on rather than corrupting the total
            if (isNaN(amount)) {
                // Log the offending value so the user can be told which cell to fix
                gs.warn('BudgetSpreadsheetTotal: skipped non-numeric value "' + rawValue + '" in ' + fileName);
                // Move to the next row without adding anything
                continue;
            }

            // Add this line item to the file subtotal (negatives subtract automatically)
            total += amount;
            // Count this row as a successfully processed line item
            rows++;
        }

        // Give the subtotal, the count, and the success flag back to recalculate()
        return {
            total: total,
            rows: rows,
            parsed: true
        };
    },

    /**
     * Turns a spreadsheet cell's text into a JavaScript number.
     * Handles "$1,200.00", "(500)" for negatives, and stray spaces.
     */
    _toNumber: function(rawValue) {
        // Force the value to a string and trim surrounding whitespace
        var text = ('' + rawValue).trim();
        // Accounting format wraps negatives in brackets - detect that before stripping them
        var bracketNegative = /^\(.*\)$/.test(text);
        // Remove every character that is not a digit, a decimal point or a minus sign
        text = text.replace(/[^0-9.\-]/g, '');
        // Convert the cleaned string into a number
        var num = parseFloat(text);
        // If the conversion failed, pass NaN back so the caller can skip this row
        if (isNaN(num))
            return NaN;
        // If the original value used brackets, force the number to be negative
        if (bracketNegative)
            num = -Math.abs(num);
        // Return the final numeric value
        return num;
    },

    /**
     * Writes the calculated net total onto the budget application record.
     */
    _writeTotal: function(recordSysId, netTotal) {
        // Open the budget application table
        var gr = new GlideRecord(this.TABLE_NAME);
        // Load the single record we need; get() returns false if it no longer exists
        if (!gr.get(recordSysId)) {
            // Log the problem rather than throwing an error the user cannot act on
            gs.error('BudgetSpreadsheetTotal: record ' + recordSysId + ' not found');
            // Exit without writing anything
            return false;
        }
        // Round to 2 decimal places - repeated floating point addition can produce values like 99.99999999
        var rounded = netTotal.toFixed(2);
        // Set the total amount field to the rounded value
        gr.setValue(this.TOTAL_FIELD, rounded);
        // Save the change to the database
        gr.update();
        // Tell the caller the write succeeded
        return true;
    },

    type: 'BudgetSpreadsheetTotal'
};
